// Process Tracerfy skip trace results - BatchData ONLY
// STRICT MOBILE-ONLY FILTER: Only import leads with confirmed mobile numbers
// PHONELESS LEADS: Store landline/unknown/no-contact for future enrichment
const webhookData = $('Tracerfy Webhook').item.json.body || $('Tracerfy Webhook').item.json;
const jobDataFromConvex = $('Get Job from Convex').item.json;
const rawInput = $input.item.json;

const tracerfyResults = rawInput.data || rawInput;
const jobData = jobDataFromConvex.job || jobDataFromConvex || {};
const leadData = jobData.leadData || [];
const queueId = webhookData.id || jobData.jobId;

let records = [];
if (typeof tracerfyResults === 'string') {
  const lines = tracerfyResults.split('\n');
  const headers = lines[0].split(',').map(h => h.trim());
  for (let i = 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const values = lines[i].split(',');
    const record = {};
    headers.forEach((h, idx) => record[h] = values[idx]?.trim() || '');
    records.push(record);
  }
} else {
  records = tracerfyResults.records || tracerfyResults.results || tracerfyResults.data || [tracerfyResults];
}

const formatPhone = (phone) => {
  if (!phone) return '';
  let cleaned = String(phone).replace(/\D/g, '');
  if (cleaned.startsWith('1') && cleaned.length === 11) cleaned = cleaned.slice(1);
  cleaned = cleaned.slice(-10);
  return cleaned.length === 10 ? `+1${cleaned}` : '';
};

const isMobileType = (phoneType) => {
  if (!phoneType) return false;
  const type = phoneType.toLowerCase().trim();
  return type === 'mobile' || type === 'wireless' || type === 'cell' || type === 'cellular';
};

const processedLeads = [];
const emailOnlyLeads = [];
const phonelessLeads = [];
let leadsWithMobile = 0;
let landlineFiltered = 0;
let unknownPhoneFiltered = 0;
let leadsNoContact = 0;

for (let i = 0; i < records.length; i++) {
  const record = records[i];
  const originalLead = leadData[i] || {};
  const propertyData = originalLead.propertyData || {};

  const mobile1 = formatPhone(record['Mobile-1'] || record['mobile_1'] || record['mobile1']);
  const mobile2 = formatPhone(record['Mobile-2'] || record['mobile_2'] || record['mobile2']);
  const mobile3 = formatPhone(record['Mobile-3'] || record['mobile_3'] || record['mobile3']);
  const primaryEmail = record['Email-1'] || record['email_1'] || record['email'] || '';

  const primaryPhoneType = (record['primary_phone_type'] || record['phone_type'] || '').toLowerCase();
  const primaryPhone = record['primary_phone'] || record['phone'] || '';

  if (primaryPhoneType === 'landline') {
    landlineFiltered++;
  } else if (primaryPhone && !mobile1 && !isMobileType(primaryPhoneType)) {
    unknownPhoneFiltered++;
  }

  let phone1 = mobile1;
  if (!phone1 && primaryPhone && isMobileType(primaryPhoneType)) {
    phone1 = formatPhone(primaryPhone);
  }

  const addr = propertyData.address || {};
  const owner = propertyData.owner || {};
  const ownerName = owner.names?.[0] || {};
  const building = propertyData.building || {};
  const valuation = propertyData.valuation || {};
  const general = propertyData.general || {};

  const distressIndicators = propertyData.distressIndicators || [];
  const distressScore = propertyData.distressScore || 0;
  const primaryDistress = propertyData.primaryDistress || distressIndicators[0] || 'general';
  const isAbsentee = propertyData.absenteeOwner === true;
  const isOutOfState = propertyData.outOfState === true;

  const stagedLead = {
    firstName: record['first_name'] || ownerName.first || originalLead.ownerName?.split(' ')[0] || '',
    lastName: record['last_name'] || ownerName.last || originalLead.ownerName?.split(' ').slice(1).join(' ') || '',
    email: primaryEmail,
    address: originalLead.address || record['address'] || addr.street || '',
    city: originalLead.city || record['city'] || addr.city || '',
    state: originalLead.state || record['state'] || addr.state || 'OH',
    zip: originalLead.zip || addr.zip || '',
    county: addr.county || '',
    ownerType: owner.type || 'individual',
    absenteeOwner: isAbsentee,
    outOfState: isOutOfState,
    tier: jobData.tier || '',
    tierName: jobData.tierName || '',
    listingType: jobData.listingType || '',
    importId: jobData.importId || '',
    importDate: jobData.importDate || new Date().toISOString().split('T')[0],
    status: 'pending',
    parcelId: originalLead.parcelId || originalLead.propertyData?.parcelId || originalLead.propertyData?.parcel_id || '',
    propertyType: general.propertyTypeDetail || general.propertyType || '',
    bedrooms: Number(building.bedroomCount || 0),
    bathrooms: Number(building.bathroomCount || 0),
    sqft: Number(building.livingAreaSquareFeet || 0),
    yearBuilt: Number(building.yearBuilt || 0),
    estimatedValue: Number(valuation.estimatedValue || 0),
    equity: Number(valuation.equity || 0),
    distressScore: distressScore,
    primaryDistress: primaryDistress,
    distressIndicators: distressIndicators
  };

  const emailLead = {
    firstName: record['first_name'] || ownerName.first || originalLead.ownerName?.split(' ')[0] || '',
    lastName: record['last_name'] || ownerName.last || originalLead.ownerName?.split(' ').slice(1).join(' ') || '',
    email: primaryEmail,
    address: originalLead.address || record['address'] || addr.street || '',
    city: originalLead.city || record['city'] || addr.city || '',
    state: originalLead.state || record['state'] || addr.state || 'OH',
    zip: originalLead.zip || addr.zip || '',
    county: addr.county || '',
    ownerType: owner.type || 'individual',
    absenteeOwner: isAbsentee,
    outOfState: isOutOfState,
    tier: jobData.tier || '',
    tierName: jobData.tierName || '',
    listingType: jobData.listingType || '',
    importId: jobData.importId || '',
    importDate: jobData.importDate || new Date().toISOString().split('T')[0],
    parcelId: originalLead.parcelId || originalLead.propertyData?.parcelId || originalLead.propertyData?.parcel_id || '',
    propertyType: general.propertyTypeDetail || general.propertyType || '',
    bedrooms: Number(building.bedroomCount || 0),
    bathrooms: Number(building.bathroomCount || 0),
    sqft: Number(building.livingAreaSquareFeet || 0),
    yearBuilt: Number(building.yearBuilt || 0),
    estimatedValue: Number(valuation.estimatedValue || 0),
    distressScore: distressScore,
    primaryDistress: primaryDistress,
    distressIndicators: distressIndicators,
    source: 'batchdata_weekly'
  };

  if (phone1) {
    leadsWithMobile++;
    processedLeads.push({ ...stagedLead, phone: phone1, phone2: mobile2, phone3: mobile3 });
  } else if (primaryEmail) {
    emailOnlyLeads.push(emailLead);
  } else {
    leadsNoContact++;

    let reason = 'no_contact';
    let src = 'tracerfy_no_contact';
    if (primaryPhoneType === 'landline') {
      reason = 'landline';
      src = 'tracerfy_landline';
    } else if (primaryPhone) {
      reason = 'unknown_type';
      src = 'tracerfy_unknown';
    }

    phonelessLeads.push({
      firstName: stagedLead.firstName,
      lastName: stagedLead.lastName,
      parcelId: stagedLead.parcelId,
      landlinePhone: (reason === 'landline') ? formatPhone(primaryPhone) : undefined,
      unknownPhone: (reason === 'unknown_type') ? formatPhone(primaryPhone) : undefined,
      email: primaryEmail || undefined,
      address: stagedLead.address,
      city: stagedLead.city,
      state: stagedLead.state,
      zip: stagedLead.zip,
      county: stagedLead.county || undefined,
      propertyType: stagedLead.propertyType || undefined,
      bedrooms: stagedLead.bedrooms || undefined,
      bathrooms: stagedLead.bathrooms || undefined,
      sqft: stagedLead.sqft || undefined,
      yearBuilt: stagedLead.yearBuilt || undefined,
      estimatedValue: stagedLead.estimatedValue || undefined,
      distressScore: stagedLead.distressScore || undefined,
      primaryDistress: stagedLead.primaryDistress || undefined,
      distressIndicators: stagedLead.distressIndicators || undefined,
      ownerType: stagedLead.ownerType || 'individual',
      absenteeOwner: stagedLead.absenteeOwner || undefined,
      outOfState: stagedLead.outOfState || undefined,
      tier: jobData.tier || '',
      tierName: jobData.tierName || '',
      listingType: jobData.listingType || '',
      importId: jobData.importId || '',
      importDate: jobData.importDate || new Date().toISOString().split('T')[0],
      skipTraceJobId: String(queueId),
      phonelessReason: reason,
      source: src
    });
  }
}

console.log('=== MOBILE-ONLY FILTER STATS ===');
console.log(`Total records: ${records.length}`);
console.log(`Leads with MOBILE: ${leadsWithMobile}`);
console.log(`Landlines filtered: ${landlineFiltered}`);
console.log(`Unknown phone type filtered: ${unknownPhoneFiltered}`);
console.log(`Email-only leads: ${emailOnlyLeads.length}`);
console.log(`Phoneless leads (stored): ${phonelessLeads.length}`);
console.log(`No contact info: ${leadsNoContact}`);

return [{ json: { 
  jobId: String(queueId), 
  tier: jobData.tier || '', 
  tierName: jobData.tierName || '', 
  listingType: jobData.listingType || '', 
  importId: jobData.importId || '', 
  importDate: jobData.importDate || new Date().toISOString().split('T')[0], 
  leadsReceived: records.length, 
  leadsWithPhone: leadsWithMobile,
  leadsEmailOnly: emailOnlyLeads.length, 
  leadsNoContact, 
  leadsPhoneless: phonelessLeads.length,
  landlineFiltered,
  unknownPhoneFiltered,
  leads: processedLeads, 
  emailOnlyLeads,
  phonelessLeads
} }];

// Sync Tracerfy-enriched seller/property identity into InsulaCRM.
// InsulaCRM is canonical; Convex staging remains intact during migration.
const processed = $('Process Skip Trace Results').first().json;
const apiBase = ($env.INSULA_CRM_BASE_URL || '').replace(/\\/$/, '');
const apiKey = $env.INSULA_CRM_API_KEY;

if (!apiBase || !apiKey) {
  console.log('InsulaCRM sync skipped: INSULA_CRM_BASE_URL/API_KEY not configured.');
  return [{ json: { ...processed, insulaSync: { skipped: true, reason: 'missing_config' } } }];
}

const leads = [
  ...(processed.leads || []).map(l => ({ ...l, _contactClass: 'mobile' })),
  ...(processed.emailOnlyLeads || []).map(l => ({ ...l, _contactClass: 'email_only' })),
  ...(processed.phonelessLeads || []).map(l => ({ ...l, _contactClass: 'phoneless' }))
];

const normalizeExternalId = (lead) => String(lead.parcelId || [lead.address, lead.city, lead.state, lead.zip].filter(Boolean).join('|') || '').trim().slice(0, 255);
const results = [];

for (const lead of leads) {
  const externalId = normalizeExternalId(lead);
  if (!externalId || !lead.firstName || !lead.lastName) {
    results.push({ status: 'skipped', reason: 'missing_identity', externalId });
    continue;
  }

  const externalSource = 'batchdata_weekly';
  const headers = { 'X-API-Key': apiKey, 'Content-Type': 'application/json' };
  const payload = {
    external_id: externalId,
    external_source: externalSource,
    first_name: lead.firstName,
    last_name: lead.lastName,
    phone: lead.phone || null,
    email: lead.email || null,
    source: 'BatchData',
    notes: JSON.stringify({
      tracerfy_enriched: true,
      contact_class: lead._contactClass,
      skip_trace_job_id: processed.jobId || null,
      distressScore: lead.distressScore || 0,
      primaryDistress: lead.primaryDistress || null,
      tier: lead.tier || null,
      listingType: lead.listingType || null,
      landlinePhone: lead.landlinePhone || null,
      unknownPhone: lead.unknownPhone || null
    }),
    property_address: lead.address || null,
    property_city: lead.city || null,
    property_state: lead.state || null,
    property_zip: lead.zip || null,
    property_type: lead.propertyType || null
  };

  try {
    const createResponse = await this.helpers.httpRequest({
      method: 'POST',
      url: apiBase + '/api/v1/leads',
      headers: { ...headers, 'Idempotency-Key': 'acquisition:tracerfy:' + externalSource + ':' + encodeURIComponent(externalId) + ':v1' },
      body: payload,
      json: true,
      returnFullResponse: false,
      timeout: 30000
    });

    let leadId = createResponse?.lead_id || null;
    let duplicate = !!createResponse?.duplicate;
    let propertyId = createResponse?.property_id || null;

    if (!leadId) {
      const lookup = await this.helpers.httpRequest({
        method: 'GET',
        url: apiBase + '/api/v1/leads?external_id=' + encodeURIComponent(externalId) + '&external_source=' + encodeURIComponent(externalSource) + '&per_page=1',
        headers,
        json: true,
        returnFullResponse: false,
        timeout: 30000
      });
      leadId = lookup?.data?.[0]?.id || lookup?.[0]?.id || null;
      propertyId = lookup?.data?.[0]?.property?.id || lookup?.[0]?.property?.id || null;
      duplicate = true;
    }

    if (leadId) {
      await this.helpers.httpRequest({
        method: 'PUT',
        url: apiBase + '/api/v1/leads/' + leadId,
        headers,
        body: { first_name: lead.firstName, last_name: lead.lastName, phone: lead.phone || null, email: lead.email || null, notes: payload.notes },
        json: true,
        returnFullResponse: false,
        timeout: 30000
      });
    }

    results.push({ status: leadId ? (duplicate ? 'updated' : 'created') : 'unresolved', leadId, propertyId, externalId, externalSource });
  } catch (error) {
    console.log('InsulaCRM Tracerfy sync failed for ' + externalId + ': ' + error.message);
    results.push({ status: 'error', externalId, externalSource, error: error.message });
  }
}

const summary = results.reduce((acc, r) => { acc[r.status] = (acc[r.status] || 0) + 1; return acc; }, {});
return [{ json: { ...processed, insulaSync: { summary, results } } }];

const processedData = $('Process Skip Trace Results').item.json;
console.log(`=== JOB COMPLETED ===`);
console.log(`Job ID: ${processedData.jobId}`);
console.log(`Tier: ${processedData.tier}`);
console.log(`Leads Received: ${processedData.leadsReceived}`);
console.log(`Leads With Phone: ${processedData.leadsWithPhone}`);
return [{ json: { jobId: processedData.jobId, tier: processedData.tier, tierName: processedData.tierName, listingType: processedData.listingType, importId: processedData.importId, status: 'completed', stats: { leadsReceived: processedData.leadsReceived, leadsWithPhone: processedData.leadsWithPhone, landlineFiltered: processedData.landlineFiltered } } }];

