// Process Tracerfy results for VoiceSDR - titleCompany table
var rawInput = $input.first().json;
var records = [];
if (typeof rawInput === 'string' || rawInput.data) {
  var csvData = typeof rawInput === 'string' ? rawInput : rawInput.data;
  var lines = csvData.split('\n').filter(function(l) { return l.trim(); });
  if (lines.length < 2) { return [{ json: { error: 'No data rows', processed: 0 } }]; }
  var headers = lines[0].split(',').map(function(h) { return h.trim().replace(/\"/g, ''); });
  for (var i = 1; i < lines.length; i++) {
    var line = lines[i].trim();
    if (!line) continue;
    var values = []; var current = ''; var inQuotes = false;
    for (var c = 0; c < line.length; c++) {
      var ch = line[c];
      if (ch === '"') { inQuotes = !inQuotes; }
      else if (ch === ',' && !inQuotes) { values.push(current.trim()); current = ''; }
      else { current += ch; }
    }
    values.push(current.trim());
    var record = {};
    for (var h = 0; h < headers.length; h++) { record[headers[h]] = (values[h] || '').replace(/^\"|\"$/g, ''); }
    records.push(record);
  }
} else { records = rawInput.records || rawInput.results || [rawInput]; }
function formatPhone(phone) {
  if (!phone) return '';
  var cleaned = String(phone).replace(/[^0-9]/g, '');
  if (cleaned.length === 11 && cleaned[0] === '1') cleaned = cleaned.slice(1);
  cleaned = cleaned.slice(-10);
  return cleaned.length === 10 ? '+1' + cleaned : '';
}
function isMobileType(phoneType) {
  if (!phoneType) return false;
  var type = phoneType.toLowerCase().trim();
  return type === 'mobile' || type === 'wireless' || type === 'cell';
}
var results = [];
for (var r = 0; r < records.length; r++) {
  var rec = records[r];
  var mobile1 = formatPhone(rec['Mobile-1']);
  var mobile2 = formatPhone(rec['Mobile-2']);
  var primaryPhone = rec['primary_phone'] || '';
  var primaryPhoneType = (rec['primary_phone_type'] || '').toLowerCase();
  var personalPhone = mobile1 || mobile2;
  if (!personalPhone && isMobileType(primaryPhoneType)) { personalPhone = formatPhone(primaryPhone); }
  var hasPhone = !!personalPhone;
  var firstName = (rec['first_name'] || '').trim();
  var lastName = (rec['last_name'] || '').trim();
  console.log(firstName + ' ' + lastName + ': ' + (personalPhone || 'NO MOBILE') + ' (type: ' + primaryPhoneType + ')');
  results.push({ json: { firstName: firstName, lastName: lastName, state: (rec['state'] || '').trim(), personPhone: personalPhone, hasPhone: hasPhone, phoneSource: 'tracerfy' } });
}
var withPhone = results.filter(function(r) { return r.json.hasPhone; }).length;
var noPhone = results.filter(function(r) { return !r.json.hasPhone; }).length;
console.log('Processed ' + results.length + ': ' + withPhone + ' with mobile, ' + noPhone + ' no mobile');
return results.length > 0 ? results : [{ json: { error: 'No records', processed: 0 } }];

// Process Tracerfy results for Ghost Rider — MOBILE ONLY
var rawInput = $input.first().json;
var grData = $('Check Ghost Rider Queue').first().json;
var parcelIds = grData.parcelIds || [];

var records = [];
if (typeof rawInput === 'string' || rawInput.data) {
  var csvData = typeof rawInput === 'string' ? rawInput : rawInput.data;
  var lines = csvData.split('\n').filter(function(l) { return l.trim(); });
  if (lines.length < 2) { return [{ json: { error: 'No data rows', processed: 0 } }]; }
  var headers = lines[0].split(',').map(function(h) { return h.trim().replace(/"/g, ''); });
  for (var i = 1; i < lines.length; i++) {
    var line = lines[i].trim();
    if (!line) continue;
    var values = []; var current = ''; var inQuotes = false;
    for (var c = 0; c < line.length; c++) {
      var ch = line[c];
      if (ch === '"') { inQuotes = !inQuotes; }
      else if (ch === ',' && !inQuotes) { values.push(current.trim()); current = ''; }
      else { current += ch; }
    }
    values.push(current.trim());
    var record = {};
    for (var h = 0; h < headers.length; h++) { record[headers[h]] = (values[h] || '').replace(/^"|"$/g, ''); }
    records.push(record);
  }
} else { records = rawInput.records || rawInput.results || [rawInput]; }

function formatPhone(phone) {
  if (!phone) return '';
  var cleaned = String(phone).replace(/[^0-9]/g, '');
  if (cleaned.length === 11 && cleaned[0] === '1') cleaned = cleaned.slice(1);
  cleaned = cleaned.slice(-10);
  return cleaned.length === 10 ? '+1' + cleaned : '';
}

function isMobileType(phoneType) {
  if (!phoneType) return false;
  var t = phoneType.toLowerCase().trim();
  return t === 'mobile' || t === 'wireless' || t === 'cell';
}

var results = [];
var withPhone = 0;
var noPhone = 0;
var skippedLandline = 0;

for (var r = 0; r < records.length; r++) {
  var rec = records[r];
  var parcelId = parcelIds[r] || '';
  var mobile1 = formatPhone(rec['Mobile-1'] || rec['mobile_1'] || '');
  var mobile2 = formatPhone(rec['Mobile-2'] || rec['mobile_2'] || '');
  var mobile3 = formatPhone(rec['Mobile-3'] || rec['mobile_3'] || '');
  var primaryPhone = rec['primary_phone'] || rec['phone'] || '';
  var primaryPhoneType = (rec['primary_phone_type'] || rec['phone_type'] || '').toLowerCase();

  // MOBILE ONLY — use Mobile-1/2/3 columns first
  var phone = mobile1 || mobile2 || mobile3;
  var phoneType = 'mobile';

  // Fallback to primary_phone ONLY if it is mobile type
  if (!phone && primaryPhone && isMobileType(primaryPhoneType)) {
    phone = formatPhone(primaryPhone);
    phoneType = 'mobile';
  }

  // Skip landline/unknown primary phones
  if (!phone && primaryPhone) {
    skippedLandline++;
  }

  var firstName = (rec['first_name'] || '').trim();
  var lastName = (rec['last_name'] || '').trim();

  if (phone && parcelId) {
    withPhone++;
    results.push({ json: { parcelId: parcelId, phone: phone, phoneType: phoneType, firstName: firstName, lastName: lastName, source: 'tracerfy' } });
  } else {
    noPhone++;
  }
}

console.log('=== GHOST RIDER TRACERFY RESULTS ===');
console.log('Total records: ' + records.length);
console.log('With mobile: ' + withPhone + ', No mobile: ' + noPhone + ', Skipped landline: ' + skippedLandline);
console.log('ParcelIds available: ' + parcelIds.length);

return results.length > 0 ? results : [{ json: { error: 'No mobile numbers found', processed: records.length } }];

// Process Tracerfy results for DishCraft leads
var items = $input.all();
var jobData = $('Get Job from Convex').first().json;
var leadMapping = JSON.parse(jobData.lead_mapping || '[]');

var results = [];

for (var i = 0; i < items.length; i++) {
  var row = items[i].json;
  var mapping = leadMapping[i] || {};

  // Skip if no phone found
  var phone = row.phone1 || row.mobile1 || row.phone2 || '';
  if (!phone) continue;

  results.push({json: {
    leadId: mapping.leadId,
    restaurantName: mapping.restaurantName,
    ownerFirstName: row.first_name || '',
    ownerLastName: row.last_name || '',
    ownerPhone: phone,
    ownerEmail: row.email1 || row.email2 || '',
    phoneType: row.phone1_type || 'unknown'
  }});
}

return results;

// Process Tracerfy results for ARN agents
var results = $input.all();
var agents = [];

for (var i = 0; i < results.length; i++) {
  var row = results[i].json;

  // Skip if no mobile phone
  var phones = row.phones || [];
  var mobilePhone = null;

  for (var j = 0; j < phones.length; j++) {
    var p = phones[j];
    var pType = (p.type || p.phone_type || '').toLowerCase();
    if (pType === 'mobile' || pType === 'cell' || pType === 'wireless') {
      mobilePhone = (p.phone || p.number || '').replace(/[^0-9]/g, '');
      if (mobilePhone.length === 11 && mobilePhone[0] === '1') {
        mobilePhone = mobilePhone.substring(1);
      }
      break;
    }
  }

  // Skip if no mobile found
  if (!mobilePhone || mobilePhone.length !== 10) continue;

  // Build agent record
  agents.push({
    json: {
      name: ((row.first_name || '') + ' ' + (row.last_name || '')).trim(),
      phone: '+1' + mobilePhone,
      brokerage: row.brokerage || row.company || '',
      triggerPropertyAddress: row.address || '',
      triggerPropertyCity: row.city || '',
      triggerPropertyZip: row.zip || '',
      scrapeSource: row.scrape_source || 'manual',
      source: 'tracerfy_arn'
    }
  });
}

return agents.length > 0 ? agents : [{json: {skip: true, reason: 'no_mobile_phones'}}];
